CREATE TABLE radar_snapshots(dataset TEXT NOT NULL,source_date TEXT NOT NULL,available_at TEXT NOT NULL,source_url TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(dataset,source_date));
CREATE INDEX radar_snapshots_available ON radar_snapshots(dataset,available_at);
CREATE TABLE radar_facts(market TEXT NOT NULL,symbol TEXT NOT NULL,kind TEXT NOT NULL,date TEXT NOT NULL,available_at TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(market,symbol,kind,date));
CREATE INDEX radar_facts_security ON radar_facts(market,symbol,available_at,date);
CREATE TABLE radar_members(market TEXT NOT NULL,symbol TEXT NOT NULL,name TEXT NOT NULL,first_seen TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(market,symbol));
CREATE TABLE radar_history(market TEXT NOT NULL,symbol TEXT NOT NULL,available_at TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(market,symbol));
CREATE TABLE radar_seed_attempts(market TEXT NOT NULL,symbol TEXT NOT NULL,attempted_at TEXT NOT NULL,status TEXT NOT NULL,PRIMARY KEY(market,symbol));
CREATE TABLE radar_runs(id TEXT PRIMARY KEY,session TEXT NOT NULL,as_of TEXT NOT NULL,config_version TEXT NOT NULL,expected INTEGER NOT NULL,phase TEXT NOT NULL,payload TEXT,created_at TEXT NOT NULL);
CREATE TABLE radar_features(run_id TEXT NOT NULL,market TEXT NOT NULL,symbol TEXT NOT NULL,eligible INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(run_id,market,symbol));
CREATE TABLE radar_candidates(run_id TEXT NOT NULL,market TEXT NOT NULL,symbol TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(run_id,market,symbol));
CREATE TABLE radar_publications(session TEXT PRIMARY KEY,run_id TEXT NOT NULL,published_at TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE radar_signals(id TEXT PRIMARY KEY,session TEXT NOT NULL,market TEXT NOT NULL,symbol TEXT NOT NULL,strategy TEXT NOT NULL,score REAL NOT NULL,reference_price REAL NOT NULL,config_version TEXT NOT NULL,available_at TEXT NOT NULL,payload TEXT NOT NULL);
CREATE INDEX radar_signals_date ON radar_signals(session);
CREATE TABLE radar_outcomes(signal_id TEXT NOT NULL,horizon INTEGER NOT NULL,exit_model TEXT NOT NULL,available_at TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(signal_id,horizon,exit_model));
CREATE TABLE radar_backtests(id TEXT PRIMARY KEY,available_at TEXT NOT NULL,config_version TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE radar_jobs(id TEXT PRIMARY KEY,status TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE radar_events(id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL,kind TEXT NOT NULL,code TEXT NOT NULL);
CREATE TABLE radar_source_checks(dataset TEXT PRIMARY KEY,checked_at TEXT NOT NULL,status TEXT NOT NULL,row_count INTEGER,source_date TEXT);
CREATE TRIGGER radar_publications_no_update BEFORE UPDATE ON radar_publications BEGIN SELECT RAISE(ABORT,'IMMUTABLE_PUBLICATION'); END;
CREATE TRIGGER radar_publications_no_delete BEFORE DELETE ON radar_publications BEGIN SELECT RAISE(ABORT,'IMMUTABLE_PUBLICATION'); END;
CREATE TRIGGER radar_signals_no_update BEFORE UPDATE ON radar_signals BEGIN SELECT RAISE(ABORT,'IMMUTABLE_SIGNAL'); END;
CREATE TRIGGER radar_signals_no_delete BEFORE DELETE ON radar_signals BEGIN SELECT RAISE(ABORT,'IMMUTABLE_SIGNAL'); END;
CREATE TRIGGER radar_outcomes_no_update BEFORE UPDATE ON radar_outcomes BEGIN SELECT RAISE(ABORT,'IMMUTABLE_OUTCOME'); END;
CREATE TRIGGER radar_outcomes_no_delete BEFORE DELETE ON radar_outcomes BEGIN SELECT RAISE(ABORT,'IMMUTABLE_OUTCOME'); END;
CREATE TRIGGER radar_backtests_no_update BEFORE UPDATE ON radar_backtests BEGIN SELECT RAISE(ABORT,'IMMUTABLE_BACKTEST'); END;
CREATE TRIGGER radar_backtests_no_delete BEFORE DELETE ON radar_backtests BEGIN SELECT RAISE(ABORT,'IMMUTABLE_BACKTEST'); END;
